#!/usr/bin/env node
'use strict';

/*
 * Vendors the browser build of @vercel/speed-insights into public/vendor so the
 * control room can load it from its own origin, the same way Leaflet and
 * MapLibre are vendored. Run `npm run vendor:speed-insights` after upgrading
 * the dependency, then commit the regenerated files.
 */

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const packageJsonPath = require.resolve('@vercel/speed-insights/package.json');
const packageDir = path.dirname(packageJsonPath);
const { version } = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));

const targetDir = path.join(root, 'public', 'vendor', 'vercel-speed-insights');
const source = path.join(packageDir, 'dist', 'index.mjs');
const license = path.join(packageDir, 'LICENSE');

if (!fs.existsSync(source)) throw new Error(`Missing Speed Insights browser build: ${source}`);
if (!fs.existsSync(license)) throw new Error(`Missing Speed Insights license: ${license}`);

const build = fs
  .readFileSync(source, 'utf8')
  .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
  .trimEnd();

fs.mkdirSync(targetDir, { recursive: true });
fs.writeFileSync(
  path.join(targetDir, 'index.js'),
  `/*! @vercel/speed-insights v${version} — Apache-2.0. Generated by scripts/sync-speed-insights.js; do not edit. */\n${build}\n`,
);
fs.copyFileSync(license, path.join(targetDir, 'LICENSE'));

console.log(`Vendored @vercel/speed-insights v${version} into public/vendor/vercel-speed-insights`);
